    Set(varEjCargando, true);
    Set(varEjTxt, IfError(Text('FolioEjemplar'.Run(c).datos), Notify("No se pudo consultar FOLIO (flujo FolioEjemplar): " & FirstError.Message, NotificationType.Error); ""));
    Set(varEj, ParseJSON(If(IsBlank(varEjTxt), "{}", varEjTxt)));
    Set(varEjCargando, false);
    If(Text(varEj.encontrado) = "SI", Collect(colConsultas, {c: c, t: Text(varEj.titulo), h: Now()}), Notify("El código " & c & " no está en FOLIO.", NotificationType.Warning)))))

